// 数据分析服务（admin HTTP 网关，转发至 core gRPC）
export interface AnalyticsService {
  // 事件量趋势
  EventTrend(
    request: ubaservicev1_EventTrendRequest,
  ): Promise<ubaservicev1_EventTrendResponse>;
  // 漏斗分析
  Funnel(
    request: ubaservicev1_FunnelRequest,
  ): Promise<ubaservicev1_FunnelResponse>;
  // 留存分析
  Retention(
    request: ubaservicev1_RetentionRequest,
  ): Promise<ubaservicev1_RetentionResponse>;
  // 维度分组聚合
  GroupBy(
    request: ubaservicev1_GroupByRequest,
  ): Promise<ubaservicev1_GroupByResponse>;
  // 活跃用户
  ActiveUsers(
    request: ubaservicev1_ActiveUsersRequest,
  ): Promise<ubaservicev1_ActiveUsersResponse>;
  // 归因分析
  Attribution(
    request: ubaservicev1_AttributionRequest,
  ): Promise<ubaservicev1_AttributionResponse>;
  // 分布分析
  Distribution(
    request: ubaservicev1_DistributionRequest,
  ): Promise<ubaservicev1_DistributionResponse>;
  // 行为序列
  BehaviorSequence(
    request: ubaservicev1_BehaviorSequenceRequest,
  ): Promise<ubaservicev1_BehaviorSequenceResponse>;
  // 用户分群/圈选
  Segmentation(
    request: ubaservicev1_SegmentationRequest,
  ): Promise<ubaservicev1_SegmentationResponse>;
  // 点击热力图
  Click(
    request: ubaservicev1_ClickRequest,
  ): Promise<ubaservicev1_ClickResponse>;
  // 用户生命周期
  Lifecycle(
    request: ubaservicev1_LifecycleRequest,
  ): Promise<ubaservicev1_LifecycleResponse>;
  // 流失与回流
  Churn(
    request: ubaservicev1_ChurnRequest,
  ): Promise<ubaservicev1_ChurnResponse>;
  // 间隔时间分析
  Interval(
    request: ubaservicev1_IntervalRequest,
  ): Promise<ubaservicev1_IntervalResponse>;
  // 矩阵/象限分析
  Matrix(
    request: ubaservicev1_MatrixRequest,
  ): Promise<ubaservicev1_MatrixResponse>;
  // 付费/营收分析
  Revenue(
    request: ubaservicev1_RevenueRequest,
  ): Promise<ubaservicev1_RevenueResponse>;
  // 会话分析
  SessionAnalysis(
    request: ubaservicev1_SessionAnalysisRequest,
  ): Promise<ubaservicev1_SessionAnalysisResponse>;
  // 同比环比/异常检测
  Anomaly(
    request: ubaservicev1_AnomalyRequest,
  ): Promise<ubaservicev1_AnomalyResponse>;
  // 新老用户对比
  NewVsOld(
    request: ubaservicev1_NewVsOldRequest,
  ): Promise<ubaservicev1_NewVsOldResponse>;
  // 热门转化路径
  PathSankey(
    request: ubaservicev1_PathSankeyRequest,
  ): Promise<ubaservicev1_PathSankeyResponse>;
  // 关卡/数值平衡分析
  LevelAnalysis(
    request: ubaservicev1_LevelAnalysisRequest,
  ): Promise<ubaservicev1_LevelAnalysisResponse>;
  // 鲸鱼用户/付费分层
  WhaleTier(
    request: ubaservicev1_WhaleTierRequest,
  ): Promise<ubaservicev1_WhaleTierResponse>;
  // 历史生命周期价值 LTV
  LTV(
    request: ubaservicev1_LTVRequest,
  ): Promise<ubaservicev1_LTVResponse>;
  // 滚服留存
  ServerRetention(
    request: ubaservicev1_ServerRetentionRequest,
  ): Promise<ubaservicev1_ServerRetentionResponse>;
  // 同时在线 PCU/ACU
  OnlineStats(
    request: ubaservicev1_OnlineStatsRequest,
  ): Promise<ubaservicev1_OnlineStatsResponse>;
  // 经济系统/代币流向
  Economy(
    request: ubaservicev1_EconomyRequest,
  ): Promise<ubaservicev1_EconomyResponse>;
}

