// 事件路径（用户行为路径，包含有序事件序列和路径指标）
export type ubaservicev1_EventPath = {
  // 转化事件名称（目标转化对应的事件名称）
  conversionEvent: string | undefined;
  conversionTime: undefined | wellKnownTimestamp;
  // 路径结束时间（最后一个节点事件时间）
  endTime: undefined | wellKnownTimestamp;
  eventDate: undefined | wellKnownTimestamp;
  first3Events: string[] | undefined;
  firstEvent: string | undefined;
  // 转化标记
  // 是否完成目标转化（如完成支付、注册等）
  isConverted: boolean | undefined;
  last3Events: string[] | undefined;
  lastEvent: string | undefined;
  // 有序事件序列（路径节点列表，按发生顺序排列）
  nodes: ubaservicev1_PathNode[] | undefined;
  pathHash: number | undefined;
  // 路径ID（唯一标识一条事件路径，hash 或 UUID）
  pathId: string | undefined;
  // 会话ID（路径所属会话）
  sessionId: string | undefined;
  // 路径指标
  // 路径起始时间（第一个节点事件时间）
  startTime: undefined | wellKnownTimestamp;
  // 步骤数（路径节点总数）
  stepCount: number | undefined;
  // 租户ID（多租户隔离，支持 SaaS 场景）
  tenantId: number | undefined;
  // 路径总时长（毫秒，start_time 到 end_time 的间隔）
  totalDurationMs: number | undefined;
  // 用户ID（路径所属用户）
  userId: number | undefined;
};

// 路径节点（事件路径中的单个事件节点，包含事件信息和对象信息）
export type ubaservicev1_PathNode = {
  // 事件名称（路径节点对应的行为事件名称）
  eventName: string | undefined;
  // 事件时间（节点对应事件发生的时间）
  eventTime: undefined | wellKnownTimestamp;
  // 对象ID（节点关联的对象唯一标识）
  objectId: string | undefined;
  // 对象类型（节点关联的对象类型，如商品、内容等）
  objectType: string | undefined;
  // 步骤索引（节点在路径中的位置，从0开始）
  stepIndex: number | undefined;
};

// 查询事件路径详情请求
export type ubaservicev1_GetEventPathRequest = {
  pathId?: string;
  viewMask?: wellKnownFieldMask;
};

