  // 最后出现时间（映射关系最近一次被使用或更新的时间）
  lastSeen?: wellKnownTimestamp;
  // 关联来源（如系统、人工、第三方平台等）
  linkSource?: string;
  // 扩展属性（用于存储自定义的业务特征或附加信息）
  properties: { [key: string]: string } | undefined;
  // 租户ID（多租户隔离，支持 SaaS 场景）
