// 会话（对应 sessions 表）
export type ubaservicev1_Session = {
  // 交互次数（本会话内用户交互总次数）
  actionCount: number | undefined;
  // 应用版本（会话发生时的应用版本号）
  appVersion: string | undefined;
  // 会话上下文
  context: { [key: string]: string } | undefined;
  country: string | undefined;
  // 设备ID（会话主体设备）
  deviceId: string | undefined;
  // 会话时长（起止时间间隔，单位秒）
  durationMs: number | undefined;
  // 会话结束时间
  endTime: undefined | wellKnownTimestamp;
  // 入口页面（会话起始页面）
  entryPage: string | undefined;
  // 会话事件数（本会话内发生的事件总数）
  eventCount: number | undefined;
  // 出口页面（会话结束页面）
  exitPage: string | undefined;
  // 全局用户ID（跨平台唯一标识用户）
  globalUserId: string | undefined;
  // IP城市（会话发生时的地理位置城市）
  ipCity: string | undefined;
  // 是否跳出（单页会话，true 表示跳出）
  isBounce: boolean | undefined;
  // 操作系统，会话发生时的操作系统信息
  os: string | undefined;
  // 页面浏览数（PV，页面浏览次数）
  pageViewCount: number | undefined;
  // 支付事件数（本会话内发生的支付事件总数）
  payEventCount: number | undefined;
  // 平台类型（会话发生的平台，如 Web、iOS、Android 等）
  platform?: string;
  // 风险等级（会话风险标记，枚举类型）
  riskLevel?: string;
  // 风险标签（会话风险标记，字符串列表）
  riskTags: string[] | undefined;
  // 会话ID（唯一标识一条会话）
  sessionId: string | undefined;
  // 会话起始时间
  startTime: undefined | wellKnownTimestamp;
  // 租户ID（多租户隔离，支持 SaaS 场景）
  tenantId: number | undefined;
  // 会话内总金额（本会话内发生的总金额，字符串类型，支持多币种）
  totalAmount: string | undefined;
  // 更新时间（会话最近一次更新的时间）
  updateTime: undefined | wellKnownTimestamp;
  // 用户ID（会话主体用户）
  userId: number | undefined;
};

