// 用户标签记录（对应 user_tag 表）
export type ubaservicev1_UserTag = {
  // 置信度（算法打标时，范围0~1）
  confidence?: number;
  createdAt?: wellKnownTimestamp;
  createdBy?: number;
  deletedAt?: wellKnownTimestamp;
  deletedBy?: number;
  // 有效时间（标签生效时间）
  effectiveTime?: wellKnownTimestamp;
  // 过期时间（标签失效时间）
  expireTime?: wellKnownTimestamp;
  // 主键ID（自增长，唯一标识一条用户标签记录）
  id?: number;
  // 标签来源（如人工打标、规则引擎、算法模型、批量导入等）
  source?: string;
  // 来源规则ID（如果是规则计算，记录规则ID）
  sourceRuleId?: number;
  // 标签ID（唯一标识一个标签）
  tagId?: number;
  // 租户ID（多租户隔离，支持 SaaS 场景）
  tenantId?: number;
  updatedAt?: wellKnownTimestamp;
  updatedBy?: number;
  // 用户ID（唯一标识一个用户）
  userId?: number;
  // 标签值（根据 tag_type 解析，实际存储值）
  value?: string;
  // 标签值显示名称（枚举值的展示名称）
  valueLabel?: string;
};

